using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public class EvalTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task ClassInit(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _appHost.Services.ConfigureHttpClientDefaults(b => b.AddStandardResilienceHandler());
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatClient: _chatClient,
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"));
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _app.StopAsync();
        await _app.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_ReturnsCoherentResponse()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsCoherentResponse));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var modelResponse = response.Text;

        scenario.Record(
            messages,
            new ChatMessage(ChatRole.Assistant, modelResponse),
            additionalContext: [new EvaluationContext("grounding", "The capital of France is Paris.")]);

        var metrics = scenario.GetAllMetrics();
        foreach (var metric in metrics)
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Identifier}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }

    [TestMethod]
    public async Task Chat_HandlesFollowUp()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_HandlesFollowUp));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about .NET Aspire in one sentence."),
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var modelResponse = response.Text;

        scenario.Record(
            messages,
            new ChatMessage(ChatRole.Assistant, modelResponse),
            additionalContext: [new EvaluationContext("grounding",
                ".NET Aspire is a cloud-ready stack for building observable, production-ready distributed applications.")]);

        var metrics = scenario.GetAllMetrics();
        foreach (var metric in metrics)
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Identifier}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }
}

